let q = query;
if (typeof q === 'string') { try { q = JSON.parse(q); } catch (e) { q = { probleme: q, activite: '' }; } }
const activite = String(q.activite || '').trim();
const nom = String(q.nom_entreprise || '').trim();
const pb = String(q.probleme || '').trim();
if (pb.length < 5) return 'Problème trop court : demande au client de préciser.';
const texte = ((activite ? 'Activité : ' + activite + '. ' : '') + (nom ? 'Entreprise : ' + nom + '. ' : '') + pb).slice(0, 1500);
return 'https://minisoft-rca.onrender.com/creer?probleme=' + encodeURIComponent(texte);
